import {questionImage,quizFiles} from './quiz-media.mjs';
export const ADDITIONAL_ACTIVITIES={
 crossword:['Crossword','Vocabulary and terminology from words and clues.'],sentence:['Sentence builder','Arrange words into a sentence; allow alternative answers.'],labels:['Label a diagram','Drag labels onto positions in a teacher-uploaded image.'],sorting:['Sort into categories','Place items into named groups or bins.'],hotspot:['Picture / map hotspot','Click the correct part of an image or map.'],audio:['Audio question','Listen to a teacher-uploaded clip and answer.'],spoken:['Recorded spoken answer','Record speech or upload an audio response.'],drawing:['Drawing / annotation','Draw, show working, or annotate a background image.'],numberline:['Number line','Place a value on an interactive number line.'],graph:['Graph / coordinate plotting','Plot points on a coordinate grid.'],correction:['Find and correct a mistake','Rewrite a sentence, calculation or code fragment.'],memory:['Memory pairs','Turn over cards and find matching pairs.'],reading:['Reading / source task','Read a passage or source and give a written response.']};
const fail=m=>Object.assign(Error(m),{status:400}),clean=(v,n)=>String(v??'').trim().slice(0,n),norm=v=>clean(v,10000).normalize('NFKC').replace(/\s+/g,' ').toLocaleLowerCase('en');
const share=(n,d,p)=>Math.round(n/d*p*100)/100;
const items=(v,min=1,max=20)=>{if(!Array.isArray(v)||v.length<min||v.length>max||v.some(x=>typeof x!=='string'||!x.trim()||x.length>1000))throw fail('Enter '+min+'–'+max+' non-empty items.');return v.map(x=>x.trim());};
const coordinate=(n,min=0,max=100)=>{const v=Number(n);if(!Number.isFinite(v)||v<min||v>max)throw fail('A position or value is outside the allowed range.');return v;};
export function makeCrossword(entries){
 const grid=Array.from({length:41},()=>Array(41).fill('')),used=Array.from({length:41},()=>Array(41).fill(0)),placed=[];
 for(let index=0;index<entries.length;index++){const word=entries[index].answer,letters=[...word];let choice=null;
  const fits=(x,y,dir)=>{const dx=dir===0?1:0,dy=1-dx;let crossings=0;for(let n=0;n<letters.length;n++){const xx=x+n*dx,yy=y+n*dy;if(xx<0||yy<0||xx>=41||yy>=41)return -1;const cell=grid[yy][xx];if(cell){if(cell!==letters[n]||(used[yy][xx]&(dir===0?1:2)))return -1;crossings++;}else if(dir===0&&(grid[yy-1]?.[xx]||grid[yy+1]?.[xx])||dir===1&&(grid[yy]?.[xx-1]||grid[yy]?.[xx+1]))return -1;}if(grid[y-dy]?.[x-dx]||grid[y+letters.length*dy]?.[x+letters.length*dx])return -1;return crossings;};
  if(!index)choice={x:Math.floor((41-letters.length)/2),y:20,dir:0};
  else{let best=0;for(let y=0;y<41;y++)for(let x=0;x<41;x++)if(grid[y][x])for(let n=0;n<letters.length;n++)if(letters[n]===grid[y][x])for(const dir of [0,1]){const xx=x-(dir===0?n:0),yy=y-(dir===1?n:0),count=fits(xx,yy,dir);if(count>best){best=count;choice={x:xx,y:yy,dir};}}}
  if(!choice)for(const y of Array.from({length:41},(_,n)=>n).sort((a,b)=>Math.abs(a-20)-Math.abs(b-20))){if(choice)break;for(let x=0;x<41&&!choice;x++)if(fits(x,y,0)===0)choice={x,y,dir:0};}
  if(!choice)throw fail('The crossword is too large. Use fewer or shorter words.');
  for(let n=0;n<letters.length;n++){const x=choice.x+(choice.dir===0?n:0),y=choice.y+(choice.dir===1?n:0);grid[y][x]=letters[n];used[y][x]|=choice.dir===0?1:2;}placed.push({...choice,length:letters.length,number:index+1,clue:entries[index].clue});
 }
 const cells=[];for(let y=0;y<41;y++)for(let x=0;x<41;x++)if(grid[y][x])cells.push({x,y});const minX=Math.min(...cells.map(c=>c.x)),minY=Math.min(...cells.map(c=>c.y)),maxX=Math.max(...cells.map(c=>c.x)),maxY=Math.max(...cells.map(c=>c.y));return{width:maxX-minX+1,height:maxY-minY+1,cells:cells.map(c=>({x:c.x-minX,y:c.y-minY})),clues:placed.map(p=>({...p,x:p.x-minX,y:p.y-minY,direction:p.dir===0?'Across':'Down'}))};
}
export function normalizeAdditional(q,r){
 switch(q.type){
 case 'crossword':{if(!Array.isArray(q.entries)||!q.entries.length||q.entries.length>12)throw fail('Add 1–12 crossword words and clues.');const entries=q.entries.map(e=>({answer:clean(e.answer,30).replace(/[\s-]/g,'').toLocaleUpperCase(),clue:clean(e.clue,1000)}));if(entries.some(e=>![...e.answer].length||[...e.answer].length>20||!e.clue||!/^[\p{L}\p{N}]+$/u.test(e.answer))||new Set(entries.map(e=>e.answer)).size!==entries.length)throw fail('Use different crossword words of up to 20 letters/numbers and add a clue to each.');r.crossword=makeCrossword(entries);r.correct=entries.map(e=>e.answer);break;}
 case 'sentence':r.acceptedAnswers=items(q.acceptedAnswers,1,10);r.tokens=r.acceptedAnswers[0].split(/\s+/).sort((a,b)=>a.localeCompare(b));if(r.tokens.length>40)throw fail('Use a sentence of up to 40 words.');break;
 case 'sorting':{if(!Array.isArray(q.groups)||!q.groups.length||q.groups.length>30)throw fail('Enter 1–30 item => category pairs.');const rows=q.groups.map(g=>({item:clean(g.item,300),category:clean(g.category,100)}));if(rows.some(g=>!g.item||!g.category)||new Set(rows.map(g=>g.item)).size!==rows.length)throw fail('Each sorting item must be different and have a category.');r.categories=[...new Set(rows.map(g=>g.category))].sort();if(r.categories.length<2||r.categories.length>8)throw fail('Use 2–8 categories.');rows.sort((a,b)=>a.item.localeCompare(b.item));r.items=rows.map(g=>g.item);r.correct=rows.map(g=>r.categories.indexOf(g.category));break;}
 case 'labels':{if(!r.image)throw fail('Upload the diagram to label.');if(!Array.isArray(q.targets)||!q.targets.length||q.targets.length>20)throw fail('Add 1–20 diagram labels and positions.');const labels=items(q.targets.map(t=>t.label));if(new Set(labels).size!==labels.length)throw fail('Use different labels.');r.labels=labels.slice().sort((a,b)=>a.localeCompare(b));r.targets=q.targets.map(t=>({x:coordinate(t.x),y:coordinate(t.y)}));r.correct=labels.map(l=>r.labels.indexOf(l));break;}
 case 'hotspot':if(!r.image)throw fail('Upload an image or map for the hotspot.');if(!Array.isArray(q.hotspots)||!q.hotspots.length||q.hotspots.length>12)throw fail('Mark at least one correct hotspot.');r.correct=q.hotspots.map(t=>({x:coordinate(t.x),y:coordinate(t.y),radius:coordinate(t.radius??8,1,40)}));break;
 case 'audio':{const [f]=quizFiles(q.audio?[q.audio]:[],{maxFiles:1,allowed:['mp3','wav','webm','mp4']});if(!f)throw fail('Upload the audio clip.');r.audio=f;r.acceptedAnswers=Array.isArray(q.acceptedAnswers)?q.acceptedAnswers.map(x=>clean(x,1000)).filter(Boolean).slice(0,10):[];break;}
 case 'spoken':r.maxSeconds=Math.round(coordinate(q.maxSeconds??60,5,120));break;
 case 'drawing':r.guidance=clean(q.guidance,5000);break;
 case 'numberline':r.minimum=coordinate(q.minimum??0,-10000,10000);r.maximum=coordinate(q.maximum??10,-10000,10000);r.step=coordinate(q.step??1,0.001,10000);if(r.maximum<=r.minimum)throw fail('The number-line maximum must exceed its minimum.');r.correct=coordinate(q.correct,r.minimum,r.maximum);r.tolerance=coordinate(q.tolerance??r.step/2,0,10000);break;
 case 'graph':r.minimum=coordinate(q.minimum??-5,-100,0);r.maximum=coordinate(q.maximum??5,1,100);if(r.maximum-r.minimum>40)throw fail('Use a graph range of no more than 40 units.');if(!Array.isArray(q.pointsKey)||!q.pointsKey.length||q.pointsKey.length>20)throw fail('Enter 1–20 points to plot.');r.correct=q.pointsKey.map(p=>({x:coordinate(p.x,r.minimum,r.maximum),y:coordinate(p.y,r.minimum,r.maximum)}));r.pointCount=r.correct.length;r.tolerance=coordinate(q.tolerance??0.4,0,2);break;
 case 'correction':r.original=clean(q.original,10000);if(!r.original)throw fail('Enter the text or working containing the mistake.');r.acceptedAnswers=Array.isArray(q.acceptedAnswers)?q.acceptedAnswers.map(x=>clean(x,10000)).filter(Boolean).slice(0,10):[];r.guidance=clean(q.guidance,5000);break;
 case 'memory':{if(!Array.isArray(q.pairs)||q.pairs.length<2||q.pairs.length>12)throw fail('Add 2–12 memory pairs.');const cards=q.pairs.flatMap((p,i)=>[{text:clean(p.left,200),pair:i},{text:clean(p.right,200),pair:i}]);if(cards.some(c=>!c.text))throw fail('Fill in both sides of each pair.');cards.sort((a,b)=>a.text.localeCompare(b.text));r.cards=cards.map(c=>c.text);r.correct=cards.map(c=>c.pair);break;}
 case 'reading':r.sourceText=clean(q.sourceText,20000);if(!r.sourceText)throw fail('Enter the reading passage or source.');r.guidance=clean(q.guidance,5000);break;
 }
 return r;
}
export function markAdditional(q,input,{draft=false}={}){let v=input,empty=false,score=null;const listTypes=['crossword','sentence','sorting','labels','memory','graph'];
 if(listTypes.includes(q.type)){v=v??[];if(!Array.isArray(v))throw fail('Enter valid activity responses.');}
 switch(q.type){
 case 'crossword':if(v.length>q.correct.length||v.some(x=>typeof x!=='string'||x.length>30))throw fail('Enter valid crossword words.');v=Array.from({length:q.correct.length},(_,i)=>clean(v[i],30).replace(/[\s-]/g,'').toLocaleUpperCase());empty=v.some(x=>!x);score=share(v.filter((x,i)=>x===q.correct[i]).length,q.correct.length,q.points);break;
 case 'sentence':if(v.length&& (v.length!==q.tokens.length||new Set(v).size!==v.length||v.some(n=>!Number.isInteger(n)||n<0||n>=q.tokens.length)))throw fail('Use each sentence tile exactly once.');empty=!v.length;score=empty?0:q.acceptedAnswers.some(a=>norm(a)===norm(v.map(n=>q.tokens[n]).join(' ')))?q.points:0;break;
 case 'sorting':case 'labels':{const count=q.correct.length,max=(q.type==='sorting'?q.categories:q.labels).length;if(v.length>count||v.some(n=>n!==null&&n!==''&&(!Number.isInteger(n)||n<0||n>=max)))throw fail('Choose valid categories or labels.');v=Array.from({length:count},(_,i)=>v[i]===undefined||v[i]===''?null:v[i]);empty=v.some(n=>n===null);score=share(v.filter((n,i)=>n===q.correct[i]).length,count,q.points);break;}
 case 'hotspot':empty=v===undefined||v===null;if(!empty){v={x:coordinate(v.x),y:coordinate(v.y)};score=q.correct.some(t=>Math.hypot(v.x-t.x,v.y-t.y)<=t.radius)?q.points:0;}break;
 case 'audio':case 'correction':case 'reading':if(v!==undefined&&typeof v!=='string')throw fail('Enter a written response.');v=clean(v,20000);empty=!v;if(!empty&&q.acceptedAnswers?.length)score=q.acceptedAnswers.some(a=>norm(a)===norm(v))?q.points:0;break;
 case 'spoken':v=quizFiles(v??[],{maxFiles:1,allowed:['mp3','wav','webm','mp4']});empty=!v.length;break;
 case 'drawing':empty=!v?.image&&!v?.description;if(!empty)v={image:v.image?questionImage(v.image):null,description:clean(v.description,5000)};else v=null;break;
 case 'numberline':empty=v===undefined||v===null||v==='';if(!empty){v=coordinate(v,q.minimum,q.maximum);score=Math.abs(v-q.correct)<=q.tolerance?q.points:0;}else v=null;break;
 case 'graph':if(v.length>q.pointCount)throw fail('Plot at most '+q.pointCount+' points.');v=v.map(p=>({x:coordinate(p.x,q.minimum,q.maximum),y:coordinate(p.y,q.minimum,q.maximum)}));empty=v.length<q.pointCount;{const remaining=q.correct.slice();let correct=0;for(const p of v){const i=remaining.findIndex(k=>Math.hypot(k.x-p.x,k.y-p.y)<=q.tolerance);if(i>=0){remaining.splice(i,1);correct++;}}score=share(correct,q.pointCount,q.points);}break;
 case 'memory':{if(v.some(p=>!Array.isArray(p)||p.length!==2||p.some(n=>!Number.isInteger(n)||n<0||n>=q.cards.length)))throw fail('Choose valid memory cards.');const flat=v.flat();if(new Set(flat).size!==flat.length)throw fail('Use each memory card only once.');if(v.some(([a,b])=>q.correct[a]!==q.correct[b]))throw fail('A selected memory pair does not match.');empty=flat.length!==q.cards.length;score=share(flat.length,q.cards.length,q.points);break;}
 }
 if(!draft&&q.required&&empty)throw fail('Complete required question '+q.id.replace('q','')+' before turning in.');return{value:v,score:q.points===0?0:empty?0:score,empty};
}
